def solve():
    counts = [1, 1, 2]
    dp = [[0] * 3 for _ in range(17)]
    dp[0][0] = 1
    for k in range(1, 17):
        for r in range(3):
            for d_mod in range(3):
                dp[k][r] += dp[k-1][(r - d_mod) % 3] * counts[d_mod]

    results = []
    for k in range(1, 17):
        ways_k = dp[k-1][2] + 2 * dp[k-1][1]
        results.append(ways_k)
    return results

print(solve())
